// ============================================================
// STEP 1: Extract all emails and decode base64 attachments
// ============================================================
const input = $input.first().json;
const data = input.body || input;
const emailsArray = data.emails || [];

if (emailsArray.length === 0 && data.email) {
  emailsArray.push(data.email);
}
if (emailsArray.length === 0) {
  throw new Error('No emails found. Keys: ' + Object.keys(data).join(', '));
}

// Build Agent 1 prompt: classify from subject + body ONLY
let classifyInput = '';
let emailMetadata = [];
let decodedAttachments = [];

for (let i = 0; i < emailsArray.length; i++) {
  const email = emailsArray[i];

  classifyInput += `\n===== EMAIL ${i + 1} =====\nFrom: ${email.from_name} <${email.from_email}>\nTo: ${email.to_name} <${email.to_email}>\nSubject: ${email.subject}\nBody:\n${email.body_plain}\n`;

  // Store metadata
  emailMetadata.push({
    email_index: email.email_index != null ? email.email_index : i,
    id: email.id,
    from_name: email.from_name,
    from_email: email.from_email,
    to_name: email.to_name,
    to_email: email.to_email,
    subject: email.subject,
    body_plain: email.body_plain,
    received_at: email.received_at,
    attachment_names: (email.attachments || []).map(a => a.file_name)
  });

  // Decode base64 attachments - extract readable text from binary
  const emailAttTexts = [];
  const attachments = email.attachments || [];
  for (let j = 0; j < attachments.length; j++) {
    const att = attachments[j];
    let extractedText = '';
    if (att.file_content_base64) {
      try {
        const buf = Buffer.from(att.file_content_base64, 'base64');
        // Extract readable ASCII/UTF-8 text from binary
        const raw = buf.toString('latin1');
        // For PDFs: extract text between BT/ET markers and parentheses
        const pdfTexts = [];
        const parenRegex = /\(([^)]{2,})\)/g;
        let match;
        while ((match = parenRegex.exec(raw)) !== null) {
          const t = match[1].replace(/\\n/g, '\n').replace(/\\\\/g, '').replace(/\\\(/g, '(').replace(/\\\)/g, ')');
          if (/[a-zA-Z0-9]{2,}/.test(t)) {
            pdfTexts.push(t);
          }
        }
        if (pdfTexts.length > 0) {
          extractedText = pdfTexts.join(' ');
        }
        // For DOCX: extract text from XML tags
        if (!extractedText || extractedText.length < 50) {
          const xmlTexts = [];
          const xmlRegex = /<w:t[^>]*>([^<]+)<\/w:t>/g;
          while ((match = xmlRegex.exec(raw)) !== null) {
            if (match[1].trim()) xmlTexts.push(match[1].trim());
          }
          if (xmlTexts.length > 0) {
            extractedText = xmlTexts.join(' ');
          }
        }
        // Fallback: grab any readable strings of 4+ chars
        if (!extractedText || extractedText.length < 50) {
          const readable = raw.match(/[\x20-\x7E]{4,}/g) || [];
          extractedText = readable.join(' ').substring(0, 5000);
        }
        // Limit to 8000 chars per attachment to stay within token limits
        extractedText = extractedText.substring(0, 8000);
      } catch(e) {
        extractedText = 'Error decoding: ' + e.message;
      }
    } else {
      extractedText = 'No base64 content provided';
    }
    emailAttTexts.push({
      file_name: att.file_name,
      file_type: att.file_type || '',
      file_category: att.file_category || '',
      extracted_text: extractedText
    });
  }
  decodedAttachments.push(emailAttTexts);
}

// Agent 1 prompt: Classify scenarios
const classifyPrompt = `You are an insurance email triage specialist. Read the following ${emailsArray.length} emails (subject and body only) and classify each into exactly ONE scenario.

SCENARIO TYPES:
- "BOR" - Broker of Record: Email requests a change of broker, broker appointment, or BOR transfer
- "Cancellation" - Policy Cancellation: Email requests to cancel an insurance policy
- "Quote" - Quote Request: Email requests a new insurance quote or pricing
- "Endorsement" - Policy endorsement or change request
- "Renewal" - Policy renewal request
- "Claim" - Insurance claim filing
- "Other" - None of the above

HOW TO CLASSIFY:
- Look at the subject line first - it usually states the intent clearly
- Confirm with the email body
- "Broker of Record" or "BOR" in subject/body = BOR
- "Cancellation" or "cancel" in subject/body = Cancellation
- "Quote" in subject/body = Quote

EMAILS TO CLASSIFY:
${classifyInput}

Return ONLY a JSON array with no markdown, no code blocks, no extra text:
[
  { "email_index": 0, "scenario": "<BOR|Cancellation|Quote|Endorsement|Renewal|Claim|Other>", "reason": "<one sentence why>" }
]`;

return [{
  json: {
    emailMetadata,
    decodedAttachments,
    classifyPrompt,
    totalEmails: emailsArray.length
  }
}];

// ============================================================
// Parse Agent 1 classification results
// Build Agent 2 prompt with decoded base64 text
// ============================================================
const input = $input.first().json;
const prepData = $('Prepare Data & Decode Base64').first().json;
const emailMetadata = prepData.emailMetadata;
const decodedAttachments = prepData.decodedAttachments;

// Parse Agent 1 response
let classifications = [];
let rawContent = '';
try {
  const choices = input.choices || (input.body && input.body.choices) || [];
  rawContent = choices[0].message.content.trim();
  let jsonStr = rawContent;
  if (jsonStr.startsWith('```')) {
    jsonStr = jsonStr.replace(/^```(?:json)?\s*\n?/, '').replace(/\n?```\s*$/, '').trim();
  }
  classifications = JSON.parse(jsonStr);
  if (!Array.isArray(classifications)) classifications = [classifications];
} catch(e) {
  for (let i = 0; i < emailMetadata.length; i++) {
    classifications.push({ email_index: i, scenario: 'Unknown', reason: 'Parse error: ' + e.message + ' | Raw: ' + rawContent.substring(0, 200) });
  }
}

// Build Agent 2 prompt: extract key details from decoded attachment text
let extractionInput = '';
for (let i = 0; i < emailMetadata.length; i++) {
  const meta = emailMetadata[i];
  const atts = decodedAttachments[i] || [];
  const scenario = (classifications[i] || {}).scenario || 'Unknown';

  extractionInput += `\n===== EMAIL ${i + 1} (Scenario: ${scenario}) =====\nSubject: ${meta.subject}\nBody: ${meta.body_plain}\n`;

  for (let j = 0; j < atts.length; j++) {
    extractionInput += `\n--- Attachment: ${atts[j].file_name} (${atts[j].file_category}) ---\nExtracted text from file:\n${atts[j].extracted_text}\n`;
  }
}

const extractPrompt = `You are an insurance document data extraction specialist. You have ${emailMetadata.length} emails with their attachment contents (text extracted from PDF/DOCX files). For EACH email, extract the following details from the ATTACHMENT TEXT CONTENT and email body.

FIELDS TO EXTRACT (return "Not found" if not present in the text):
- policy_number: Any policy number (e.g. "AUTO-TX-4589231", "POL-XXX", etc.)
- vin_number: Vehicle Identification Number (17-character alphanumeric)
- policy_type: Type of insurance (Auto, Home, Collector Vehicle, Commercial, etc.)
- insurance_carrier: Name of the insurance company/carrier
- customer_id: Customer ID or client reference number
- quote_number: Quote reference number
- customer_name: Full name of the customer/insured/policyholder
- license_number: Driver's license number
- attachment_type: What kind of document each attachment is (e.g. "BOR Letter", "Cancellation Form", "Insurance Application")
- email_subject: The email subject line
- email_body_summary: 2-3 sentence summary of the email

IMPORTANT: Extract values ONLY from the actual text content provided. Look carefully through the extracted attachment text for these fields. Many details are inside the attachment text, not the email body.

EMAILS AND ATTACHMENTS:
${extractionInput}

Return ONLY a JSON array with no markdown, no code blocks, no extra text:
[
  {
    "email_index": 0,
    "policy_number": "<value or Not found>",
    "vin_number": "<value or Not found>",
    "policy_type": "<value or Not found>",
    "insurance_carrier": "<value or Not found>",
    "customer_id": "<value or Not found>",
    "quote_number": "<value or Not found>",
    "customer_name": "<value or Not found>",
    "license_number": "<value or Not found>",
    "attachment_type": "<description of attachments>",
    "email_subject": "<subject>",
    "email_body_summary": "<summary>"
  }
]`;

return [{
  json: {
    classifications,
    emailMetadata,
    decodedAttachments,
    extractPrompt
  }
}];

// ============================================================
// Combine Agent 1 + Agent 2 results
// Build Agent 3 prompt for professional response
// ============================================================
const input = $input.first().json;
const prevData = $('Parse Classification & Prepare Extraction').first().json;
const classifications = prevData.classifications;
const emailMetadata = prevData.emailMetadata;

// Parse Agent 2 extraction results
let extractions = [];
let rawContent = '';
try {
  const choices = input.choices || (input.body && input.body.choices) || [];
  rawContent = choices[0].message.content.trim();
  let jsonStr = rawContent;
  if (jsonStr.startsWith('```')) {
    jsonStr = jsonStr.replace(/^```(?:json)?\s*\n?/, '').replace(/\n?```\s*$/, '').trim();
  }
  extractions = JSON.parse(jsonStr);
  if (!Array.isArray(extractions)) extractions = [extractions];
} catch(e) {
  for (let i = 0; i < emailMetadata.length; i++) {
    extractions.push({
      email_index: i, policy_number: 'Not found', vin_number: 'Not found',
      policy_type: 'Not found', insurance_carrier: 'Not found',
      customer_id: 'Not found', quote_number: 'Not found',
      customer_name: 'Not found', license_number: 'Not found',
      attachment_type: 'Not found', email_subject: emailMetadata[i].subject,
      email_body_summary: 'Extraction parse error: ' + e.message
    });
  }
}

// Build combined summary for Agent 3
let responseSummary = '';
for (let i = 0; i < emailMetadata.length; i++) {
  const meta = emailMetadata[i];
  const classif = classifications[i] || {};
  const extract = extractions[i] || {};

  responseSummary += `\n===== EMAIL ${i + 1} =====\nFrom: ${meta.from_name} <${meta.from_email}>\nSubject: ${meta.subject}\nEmail Scenario: ${classif.scenario || 'Unknown'}\nClassification Reason: ${classif.reason || 'N/A'}\nAttachments: ${meta.attachment_names.join(', ')}\n\nExtracted Key Details:\n- Policy Number: ${extract.policy_number || 'Not found'}\n- VIN Number: ${extract.vin_number || 'Not found'}\n- Policy Type: ${extract.policy_type || 'Not found'}\n- Insurance Carrier: ${extract.insurance_carrier || 'Not found'}\n- Customer ID: ${extract.customer_id || 'Not found'}\n- Quote Number: ${extract.quote_number || 'Not found'}\n- Customer Name: ${extract.customer_name || 'Not found'}\n- License Number: ${extract.license_number || 'Not found'}\n- Attachment Type: ${extract.attachment_type || 'Not found'}\n`;
}

const responsePrompt = `You are a professional insurance operations assistant at Wonderland Global Insurance. Generate a professional response email for EACH of the ${emailMetadata.length} emails below.

For each response:
1. Address the sender by name
2. Acknowledge receipt of their email and ALL attachments by filename
3. State: "Email Scenario: <scenario>" clearly
4. List ALL extracted key details in a clean format:
   - Policy Number: <value>
   - VIN Number: <value>
   - Policy Type: <value>
   - Insurance Carrier: <value>
   - Customer ID: <value>
   - Quote Number: <value>
   - Customer Name: <value>
   - License Number: <value>
   - Attachment Type: <value>
5. For items marked "Not found", say: "This detail was not found in the provided documents. Please provide this information at your earliest convenience."
6. Add category-specific next steps:
   - BOR: "Your Broker of Record change request is being processed. The transfer will be completed within 5-7 business days."
   - Cancellation: "Your cancellation request has been received. We will process the cancellation and any applicable refund will be calculated and communicated within 3-5 business days."
   - Quote: "Your quote request and application have been received. Our underwriting team will review the details and provide a quote within 2-3 business days."
7. Sign as:\n   Best Regards,\n   Wonderland Team\n   Email Processing Division\n   Emailprocessing@wonderlandglobal.com\n   Phone: (800) 555-0199

EMAILS WITH CLASSIFICATION AND EXTRACTED DETAILS:
${responseSummary}

Return ONLY a JSON array (no markdown, no code blocks):
[
  { "email_index": 0, "response_body": "<full professional response>" }
]`;

return [{
  json: {
    classifications,
    extractions,
    emailMetadata,
    responsePrompt
  }
}];

// ============================================================
// Build the final webhook response to send back to HTML
// ============================================================
const input = $input.first().json;
const prevData = $('Combine Results & Prepare Response').first().json;
const classifications = prevData.classifications || [];
const extractions = prevData.extractions || [];
const emailMetadata = prevData.emailMetadata || [];

// Parse Agent 3 generated responses
let responses = [];
try {
  const choices = input.choices || (input.body && input.body.choices) || [];
  let content = choices[0].message.content.trim();
  if (content.startsWith('```')) {
    content = content.replace(/^```(?:json)?\s*\n?/, '').replace(/\n?```\s*$/, '').trim();
  }
  responses = JSON.parse(content);
  if (!Array.isArray(responses)) responses = [responses];
} catch(e) {
  for (let i = 0; i < emailMetadata.length; i++) {
    const c = classifications[i] || {};
    responses.push({
      email_index: i,
      response_body: 'Dear ' + emailMetadata[i].from_name + ',\n\nThank you for your email regarding "' + emailMetadata[i].subject + '".\n\nEmail Scenario: ' + (c.scenario || 'Under Review') + '\n\nWe have received your request and attached documents. Our team is currently reviewing the details and will respond with a full assessment shortly.\n\nBest Regards,\nWonderland Team\nEmail Processing Division\nEmailprocessing@wonderlandglobal.com\nPhone: (800) 555-0199'
    });
  }
}

// Build final results array
const results = [];
for (let i = 0; i < emailMetadata.length; i++) {
  const meta = emailMetadata[i];
  const classif = classifications[i] || {};
  const extract = extractions[i] || {};
  const resp = responses.find(r => r.email_index === i) || responses[i] || {};

  results.push({
    email_index: meta.email_index != null ? meta.email_index : i,
    email_id: meta.id || null,
    email_subject: meta.subject,
    classification: {
      category: classif.scenario || 'Unknown',
      reason: classif.reason || '',
      confidence: classif.confidence || null
    },
    extracted_details: {
      policy_number: extract.policy_number || 'Not found',
      vin_number: extract.vin_number || 'Not found',
      policy_type: extract.policy_type || 'Not found',
      insurance_carrier: extract.insurance_carrier || 'Not found',
      customer_id: extract.customer_id || 'Not found',
      quote_number: extract.quote_number || 'Not found',
      customer_name: extract.customer_name || 'Not found',
      license_number: extract.license_number || 'Not found',
      attachment_type: extract.attachment_type || 'Not found',
      email_subject: extract.email_subject || meta.subject,
      email_body_summary: extract.email_body_summary || ''
    },
    response: {
      from_name: 'Wonderland Team',
      from_email: 'Emailprocessing@wonderlandglobal.com',
      to_name: meta.from_name,
      to_email: meta.from_email,
      subject: 'RE: ' + meta.subject,
      body: resp.response_body || 'Thank you for your email. We are processing your request.',
      sent_at: new Date().toISOString()
    },
    attachments_processed: meta.attachment_names || []
  });
}

return [{
  json: {
    success: true,
    total_processed: results.length,
    processed_at: new Date().toISOString(),
    results
  }
}];
